SUM[-1:-1]=['<h3>10.7 הליך הפסילה והסעדים</h3>', '<p>בבחירות לכנסת, ועדת הבחירות המרכזית מכריעה בבקשות לפסול רשימה או מועמד. כדי שהפסילה תיכנס לתוקף, נדרש אישור של בית המשפט העליון, והדיון נעשה בהרכב מורחב. אם הוועדה דחתה בקשת פסילה, ניתן לערער על כך לבית המשפט העליון. בית המשפט בוחן את החומר הראייתי בעצמו ואינו מסתפק בהכרעת הוועדה, שהיא גוף פוליטי. זו הסיבה לכך שההלכות המרכזיות בנושא מתגבשות בבית המשפט העליון, ולכך שאחוז הפסילות שאושרו נמוך בהרבה מאחוז הבקשות.</p>']
